<template><div class="grid"><div class="glass panel"><div class="panel-top"><h3>{{item.id?'Story tahrirlash':'Yangi story'}}</h3><button v-if="item.id" class="link-btn" @click="reset">Bekor qilish</button></div><p class="help">Sentences: <code>English | Uzbek</code>. Questions: <code>savol | variant1 | variant2 | variant3 | to‘g‘ri</code>.</p><form @submit.prevent="$emit('save',{...item})"><div class="row three"><label>CEFR<select v-model="item.cefr"><option>A1</option><option>A2</option><option>B1</option><option>B2</option><option>C1</option></select></label><label>Level<select v-model.number="item.level"><option v-for="n in 15" :key="n" :value="n">Level {{n}}</option></select></label><label>Daqiqa<input v-model.number="item.minutes" type="number" min="1" max="20" /></label></div><div class="row"><label>Uzbek title<input v-model.trim="item.title" required /></label><label>English title<input v-model.trim="item.titleEn" required /></label></div><label>Sentences<textarea v-model="item.sentencesRaw" rows="8" required/></label><label>Questions<textarea v-model="item.questionsRaw" rows="9"/></label><button class="primary" :disabled="saving">{{saving?'Saqlanmoqda…':item.id?'Saqlash':'Story qo‘shish'}}</button></form></div><div class="glass panel"><div class="panel-top"><h3>Custom stories <span>{{items.length}}</span></h3></div><div v-if="!items.length" class="empty">Hali custom story yo‘q.</div><div v-for="x in items" :key="x.id" class="item"><div><b>{{x.story.title}}</b><span>{{x.story.cefr}} · Level {{x.story.level}}</span><small>{{x.story.questions?.length||0}} savol</small></div><div class="actions"><button @click="$emit('edit',x)"><i class="ti ti-pencil"></i></button><button class="danger" @click="$emit('delete',x.id)"><i class="ti ti-trash"></i></button></div></div></div></div></template>
<script setup>import {ref,watch} from 'vue';const props=defineProps({items:Array,initial:Object,saving:Boolean});const emit=defineEmits(['save','edit','delete']);const item=ref({...props.initial});watch(()=>props.initial,v=>item.value={...v},{deep:true});function reset(){item.value={title:'',titleEn:'',cefr:'A1',level:1,minutes:3,sentencesRaw:'',questionsRaw:''}}</script><style scoped>@import './editor.css';</style>
